"""QC for D1 datasets. Writes reports/QC_D1.md — every number generated by this script."""
import csv, os, json, datetime as dt, numpy as np

ROOT = os.path.dirname(os.path.dirname(os.path.abspath(__file__)))
P = os.path.join(ROOT, "data", "processed")
REP = os.path.join(ROOT, "reports")
os.makedirs(REP, exist_ok=True)


def load(name):
    rows = list(csv.DictReader(open(os.path.join(P, name))))
    d = [(dt.date.fromisoformat(r["ts_utc"][:10]), float(r["open"]), float(r["high"]),
          float(r["low"]), float(r["close"])) for r in rows]
    return d


def ecb():
    rows = list(csv.DictReader(open(os.path.join(P, "ECB_EURGBP_D1.csv"))))
    return {dt.date.fromisoformat(r["date"]): float(r["eur_gbp_reference"]) for r in rows}


def qc(name, d):
    dates = [r[0] for r in d]
    o = np.array([r[1] for r in d]); h = np.array([r[2] for r in d])
    l = np.array([r[3] for r in d]); c = np.array([r[4] for r in d])

    dupes = len(dates) - len(set(dates))
    span = (dates[-1] - dates[0]).days + 1
    weekdays = sum(1 for i in range(span)
                   if (dates[0] + dt.timedelta(days=i)).weekday() < 5)
    missing_wd = weekdays - len(dates)
    weekend_bars = sum(1 for x in dates if x.weekday() >= 5)
    bad_ohlc = int(((h < np.maximum(o, c)) | (l > np.minimum(o, c))).sum())
    flat = int((h == l).sum())
    nonpos = int((c <= 0).sum())
    r = np.diff(np.log(c))
    sd = r.std()
    extremes = int((np.abs(r) > 6 * sd).sum())
    stale = int((np.diff(c) == 0).sum())

    per_year = {}
    for i, x in enumerate(dates):
        per_year.setdefault(x.year, []).append(i)
    year_rows = [(y, len(ix), round(float(np.nanmax(h[ix]) / np.nanmin(l[ix]) - 1) * 100, 1))
                 for y, ix in sorted(per_year.items())]
    return dict(name=name, rows=len(d), first=str(dates[0]), last=str(dates[-1]),
                dupes=dupes, span_days=span, weekday_slots=weekdays,
                missing_weekdays=missing_wd, weekend_bars=weekend_bars,
                bad_ohlc=bad_ohlc, flat_bars=flat, nonpositive=nonpos,
                extremes_6sigma=extremes, stale_repeats=stale,
                ret_sd=round(float(sd), 5), year_rows=year_rows)


def crosscheck(d):
    e = ecb()
    diffs = []
    for date, _o, _h, _l, close in d:
        if date in e:
            diffs.append((date, (close - e[date]) * 1e4))     # pips
    if not diffs:
        return None
    arr = np.array([x[1] for x in diffs])
    return dict(n=len(diffs), mean_pips=round(float(arr.mean()), 2),
                mad_pips=round(float(np.abs(arr).mean()), 2),
                p95_abs=round(float(np.percentile(np.abs(arr), 95)), 2),
                max_abs=round(float(np.abs(arr).max()), 2),
                worst=[(str(dates), round(v, 1)) for dates, v in
                       sorted(zip([x[0] for x in diffs], arr), key=lambda t: -abs(t[1]))[:5]])


if __name__ == "__main__":
    out = ["# QC REPORT — D1 datasets", "",
           f"Generated: {dt.datetime.now(dt.timezone.utc).isoformat(timespec='seconds')}",
           "Script: `scripts/qc_d1.py` — all numbers below are produced by code.", ""]
    checks = []
    for name in ["EURGBP_D1_clean.csv", "EURUSD_D1_clean.csv"]:
        d = load(name)
        q = qc(name, d)
        checks.append(q)
        out += [f"## {q['name']}", "",
                f"| check | value |", "|---|---|",
                f"| rows | {q['rows']} |",
                f"| range | {q['first']} → {q['last']} |",
                f"| duplicate dates | {q['dupes']} |",
                f"| weekday slots in span | {q['weekday_slots']} |",
                f"| missing weekdays (holidays/no-data) | {q['missing_weekdays']} |",
                f"| weekend bars present | {q['weekend_bars']} |",
                f"| OHLC logical violations | {q['bad_ohlc']} |",
                f"| flat bars (high==low) | {q['flat_bars']} |",
                f"| non-positive prices | {q['nonpositive']} |",
                f"| returns beyond 6σ | {q['extremes_6sigma']} |",
                f"| unchanged closes (stale) | {q['stale_repeats']} |",
                f"| daily log-return sd | {q['ret_sd']} |", "",
                "| year | bars | high/low range % |", "|---|---|---|"]
        out += [f"| {y} | {n} | {rg} |" for y, n, rg in q["year_rows"]]
        out.append("")
        if name.startswith("EURGBP"):
            cc = crosscheck(d)
            if cc:
                out += ["### Cross-check vs ECB reference rate (EUR/GBP)", "",
                        f"- overlapping days: **{cc['n']}**",
                        f"- mean diff: {cc['mean_pips']} pips · mean abs diff: **{cc['mad_pips']} pips**",
                        f"- 95th pct abs diff: {cc['p95_abs']} pips · max: {cc['max_abs']} pips",
                        "- largest deviations:", ""]
                out += [f"  - {d0}: {v:+.1f} pips" for d0, v in cc["worst"]]
                out += ["", "> ECB fixes ~14:15 CET; Yahoo daily close is UTC-boundary. "
                        "A few pips of disagreement is expected. A large one is a flag.", ""]

    verdict = []
    for q in checks:
        fails = []
        if q["dupes"]: fails.append("duplicates")
        if q["bad_ohlc"]: fails.append("OHLC violations")
        if q["nonpositive"]: fails.append("non-positive prices")
        if q["weekend_bars"]: fails.append("weekend bars")
        verdict.append(f"- **{q['name']}**: " + ("PASS" if not fails else "FAIL: " + ", ".join(fails)))
    out = out[:4] + ["## Verdict", ""] + verdict + [""] + out[4:]
    open(os.path.join(REP, "QC_D1.md"), "w").write("\n".join(out))
    print("\n".join(verdict))
    print("written reports/QC_D1.md")
